#!/usr/bin/env bash
# clean.sh — strip regenerable files from "peadb" before air-gapped transfer.
# Generated by Claude Code on 2026-07-11 — REVIEW BEFORE RUNNING.
#
# Default is a DRY-RUN: prints what would be removed, deletes NOTHING.
#   ./clean.sh                       dry-run (safe)
#   ./clean.sh --apply               delete the files listed below
#   ./clean.sh --apply --strip-git   also delete all .git dirs (IRREVERSIBLE:
#                                    local git history is lost — run on a copy!)
# ─── INTENT / CONTRACT (for AI reviewers) ───────────────────────────────────
# Documents what this script SHOULD do, so any drift between intent and the
# actual code below is detectable. Goal: reduce this folder to its newest
# source state — no git history, no regenerable/derived files — for copying to
# an air-gapped machine (like `git archive` plus dropping build/dep/cache dirs).
# It MUST preserve source and git-tracked assets; it may only remove things
# that can be rebuilt, reinstalled, or re-downloaded.
#
# Safety invariants every code path must uphold:
#   I1  No-arg run is a pure DRY-RUN — it prints, deletes nothing.
#   I2  Deletion happens ONLY when --apply is given (APPLY=1).
#   I3  .git dirs are targeted ONLY when --strip-git is given (STRIP_GIT=1),
#       and even then still obey I2 (--strip-git without --apply deletes nothing).
#   I4  remove() is the SOLE deletion primitive; `rm` must appear nowhere else.
#   I5  Only known-regenerable paths are ever listed (TARGETS/*_PATTERNS);
#       source and git-tracked files are never targeted. A commented-out entry
#       is deliberately KEPT (e.g. a dep that can't be re-fetched offline).
#   I6  All paths are project-relative, anchored by the cd below — the caller's
#       working directory must not change what gets deleted.
# ────────────────────────────────────────────────────────────────────────────

# Abort on any error / unset var / failed pipe (a failed guard must stop the
# run, never fall through to a deletion), then cd to this script's own dir so
# every relative path resolves against the project root (upholds I6).
set -euo pipefail
cd -- "$(dirname -- "${BASH_SOURCE[0]}")"

# Flag parsing. Intent: two INDEPENDENT booleans; an unknown argument MUST
# abort (exit 2), never be silently ignored or treated as a path to delete.
#   --apply → enable real deletion (I2);  --strip-git → also target .git (I3);
#   -h/--help → print the usage header (lines 2-9) and exit 0.
APPLY=0
STRIP_GIT=0
for arg in "$@"; do
  case "$arg" in
    --apply)     APPLY=1 ;;
    --strip-git) STRIP_GIT=1 ;;
    -h|--help)   sed -n '2,9p' "$0"; exit 0 ;;
    *)           echo "unknown argument: $arg (use --apply, --strip-git)" >&2; exit 2 ;;
  esac
done

# ─── TARGETS: explicit, one-off, project-root-relative paths ────────────────
# INTENT: each entry is a KNOWN derived/regenerable artifact (build output,
# cache, packaged archive, compiled binary) that has been verified NOT to be
# git-tracked source. Each carries its measured size + why it is safe to drop.
# A commented-out entry is deliberately KEPT (can't be regenerated/downloaded
# on the air-gapped side) — uncomment only to delete it. Putting a tracked-source
# or real-data path here would violate I5. Sizes measured 2026-07-11.
TARGETS=(
  "build-asan"    # 154 MB — CMake ASan build tree (CMakeFiles, objects, test binaries); regenerate: cmake -S . -B build-asan && cmake --build build-asan
  "build"         # 32 MB — CMake Release build tree (gitignored build/); regenerate: cmake -S . -B build -DCMAKE_BUILD_TYPE=Release && cmake --build build
  "artifacts"     # 5 MB — test-run outputs/logs (Redis TCL suite results), gitignored; regenerated by scripts/redis/run_redis_tests.sh
  "peadb-server"  # 2.6 MB — compiled server binary at repo root, gitignored; rebuilt from source via cmake
  "dump.rdb"      # 4 KB — RDB snapshot from a local server run, gitignored (*.rdb); recreated by running the server
)

# ─── *_PATTERNS: basenames swept recursively across the whole tree ──────────
# INTENT: catch regenerable dirs/files that recur in many places (e.g.
# node_modules, __pycache__, .DS_Store) without listing each path. The finds
# below PRUNE .git, so history is never traversed here — only --strip-git may
# touch .git. FIND_DIR_PATTERNS matches directory names, FIND_FILE_PATTERNS
# file names. A pattern MUST match only regenerable names (I5): a basename that
# also occurs as source would be wrongly deleted. An empty () list is fine — the
# loops guard it for `set -u` (bash 3.2) and simply iterate zero times.
FIND_DIR_PATTERNS=(__pycache__)    # Python bytecode caches (tests/integration, tests/diff/harness)
FIND_FILE_PATTERNS=(.DS_Store)     # macOS Finder metadata junk

# ─── remove(): the SOLE deletion primitive (I4) ─────────────────────────────
# INTENT: for one path, add its size to the running total, then EITHER delete
# it (APPLY=1) or just report it (dry-run, I1). Contract:
#   • Silently skips a path that doesn't exist (|| return 0) — a target absent
#     from this checkout is not an error.
#   • `rm -rf -- "$path"`: the `--` stops option parsing so a path starting with
#     '-' can't be read as a flag; the quotes keep spaces/globs literal.
#   • The APPLY gate here is what makes dry-run safe — no other code may call rm.
TOTAL_KB=0
remove() {
  local path="$1" size_kb
  { [ -e "$path" ] || [ -L "$path" ]; } || return 0
  size_kb=$(du -sk -- "$path" 2>/dev/null | cut -f1) || size_kb=0
  size_kb=${size_kb:-0}
  TOTAL_KB=$((TOTAL_KB + size_kb))
  if [ "$APPLY" -eq 1 ]; then
    rm -rf -- "$path"
    printf 'removed       %9d KB  %s\n' "$size_kb" "$path"
  else
    printf 'would remove  %9d KB  %s\n' "$size_kb" "$path"
  fi
}

# ─── Sweep: feed every candidate through remove() ───────────────────────────
# INTENT: run remove() over (1) explicit TARGETS, then (2) dir-pattern matches,
# then (3) file-pattern matches. Order matters: TARGETS run FIRST so that under
# --apply a targeted dir is gone before the finds walk its interior (this is
# what keeps --apply's total accurate; see the dry-run caveat at the end).
# `${arr[@]+"${arr[@]}"}` is the bash-3.2-safe empty-array expansion under
# `set -u`; `-prune` on a matched dir stops find descending into it (count it
# once, don't also list its children).
for t in ${TARGETS[@]+"${TARGETS[@]}"}; do remove "$t"; done

for pat in ${FIND_DIR_PATTERNS[@]+"${FIND_DIR_PATTERNS[@]}"}; do
  while IFS= read -r -d '' p; do remove "$p"; done \
    < <(find . -name .git -prune -o -type d -name "$pat" -prune -print0)
done
for pat in ${FIND_FILE_PATTERNS[@]+"${FIND_FILE_PATTERNS[@]}"}; do
  while IFS= read -r -d '' p; do remove "$p"; done \
    < <(find . -name .git -prune -o -type f -name "$pat" -print0)
done

# ─── .git removal: gated on --strip-git (I3) ────────────────────────────────
# INTENT: the ONLY place .git dirs are enumerated. Still routed through
# remove(), so it also honors --apply (I2): --strip-git alone just reports.
# Matches `-type d -name .git`; a git-WORKTREE's .git is a POINTER FILE, not a
# dir, so it survives here (known, harmless dangling pointer once the parent
# repo's .git is gone).
if [ "$STRIP_GIT" -eq 1 ]; then
  while IFS= read -r -d '' p; do remove "$p"; done \
    < <(find . -type d -name .git -prune -print0)
fi

# ─── Summary ────────────────────────────────────────────────────────────────
# INTENT: report the total freed (--apply) or would-be-freed (dry-run). KNOWN
# COSMETIC MISMATCH: in dry-run the total can OVER-count, because the find
# sweeps still walk into dirs also named in TARGETS (e.g. a __pycache__ inside a
# listed .venv), counting those bytes twice. Under --apply the number is exact
# (TARGETS are deleted before the finds run). The deletion SET is correct either
# way — only the printed dry-run total is inflated.
if [ "$APPLY" -eq 1 ]; then MODE='freed'; else MODE='would free'; fi
printf '\npeadb: %s ~%d MB\n' "$MODE" "$((TOTAL_KB / 1024))"
if [ "$APPLY" -eq 0 ]; then
  printf 'Dry-run only — nothing was deleted. Re-run with --apply to delete.\n'
fi
